package co.edu.fet.agendad.analitica;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/v1") public class AnaliticaController {
 private final JdbcTemplate db;private final ObjectMapper json; public AnaliticaController(JdbcTemplate d,ObjectMapper j){db=d;json=j;}
 @KafkaListener(topics={"citas.reservadas","citas.canceladas","citas.estado"}) @Transactional public void consumir(String raw){try{JsonNode e=json.readTree(raw);UUID id=UUID.fromString(e.path("eventoId").asText());if(db.queryForObject("select count(*) from analitica.evento_procesado where evento_id=?",Integer.class,id)>0)return;UUID negocio=UUID.fromString(e.path("negocioId").asText()),prof=UUID.fromString(e.path("profesionalId").asText()),serv=UUID.fromString(e.path("servicioId").asText());LocalDate fecha=Instant.parse(e.path("inicio").asText()).atZone(ZoneId.of("America/Bogota")).toLocalDate();int minutos=(int)Duration.between(Instant.parse(e.path("inicio").asText()),Instant.parse(e.path("fin").asText())).toMinutes();db.update("insert into analitica.metrica_diaria(negocio_id,fecha,profesional_id,servicio_id) values(?,?,?,?) on conflict do nothing",negocio,fecha,prof,serv);String topic=e.has("estadoNuevo")?"estado":raw.contains("canceladaPor")?"cancelada":"reservada";String field=switch(topic){case "cancelada"->"canceladas";case "estado"->e.path("estadoNuevo").asText().equals("ATENDIDA")?"atendidas":"no_asistio";default->"reservadas";};String extra=topic.equals("reservada")?", minutos_ocupados=minutos_ocupados+?":"";List<Object>a=new ArrayList<>();if(topic.equals("reservada"))a.add(minutos);a.addAll(List.of(negocio,fecha,prof,serv));db.update("update analitica.metrica_diaria set "+field+"="+field+"+1"+extra+" where negocio_id=? and fecha=? and profesional_id=? and servicio_id=?",a.toArray());db.update("insert into analitica.evento_procesado(evento_id) values(?)",id);}catch(Exception ex){throw new IllegalStateException(ex);}}
 @GetMapping("/metricas") public Map<String,Object> metricas(@RequestHeader("X-Negocio-Id") UUID negocio,@RequestParam LocalDate desde,@RequestParam LocalDate hasta){Map<String,Object> m=db.queryForMap("select coalesce(sum(reservadas),0) total,coalesce(sum(atendidas),0) atendidas,coalesce(sum(no_asistio),0) no_asistio,coalesce(sum(canceladas),0) canceladas,coalesce(sum(minutos_ocupados),0) minutos from analitica.metrica_diaria where negocio_id=? and fecha between ? and ?",negocio,desde,hasta);long total=((Number)m.get("total")).longValue(), no=((Number)m.get("no_asistio")).longValue();return Map.of("desde",desde,"hasta",hasta,"totalCitas",total,"atendidas",m.get("atendidas"),"noAsistio",no,"canceladas",m.get("canceladas"),"ocupacion",0,"tasaInasistencia",total==0?0:Math.round(no*10000.0/total)/100.0,"topServicios",List.of());}
}
